//! Python-compatible primitives the ported code relies on for byte-identical output:
//! `round()`, float `repr()`, `format(x, 'g')`, `str.__repr__`, `str.isspace`/`strip`,
//! truthiness and `str()` of JSON values, `datetime.fromisoformat`.
//!
//! Each function documents where it is narrower than CPython. Golden vectors generated by
//! CPython (`tests-golden/gen_domain.py`) pin the behaviour.

use std::str::FromStr;

use chrono::{Datelike, NaiveDate, NaiveDateTime, NaiveTime};
use regex::Regex;
use rust_decimal::Decimal;
use serde_json::Value;

/// `str.isspace()` for one character: Unicode White_Space plus U+001C..U+001F
/// (CPython counts the information separators as whitespace).
pub fn is_space(c: char) -> bool {
    c.is_whitespace() || ('\u{1c}'..='\u{1f}').contains(&c)
}

/// `str.strip()` with no arguments.
pub fn strip(s: &str) -> &str {
    s.trim_matches(is_space)
}

/// `str.split()` with no arguments.
pub fn split_whitespace(s: &str) -> Vec<&str> {
    s.split(is_space).filter(|t| !t.is_empty()).collect()
}

/// `str.upper()` (full Unicode case mapping, as CPython).
pub fn upper(s: &str) -> String {
    s.to_uppercase()
}

/// `s[:n]` (code points).
pub fn prefix_chars(s: &str, n: usize) -> &str {
    match s.char_indices().nth(n) {
        Some((i, _)) => &s[..i],
        None => s,
    }
}

/// `str.title()` for ASCII-style words: upper-case the first cased letter after a non-letter,
/// lower-case the rest.
pub fn title(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut prev_cased = false;
    for c in s.chars() {
        if prev_cased {
            out.extend(c.to_lowercase());
        } else {
            out.extend(c.to_uppercase());
        }
        prev_cased = c.is_alphabetic();
    }
    out
}

/// Compile a regex written in Python syntax where `\s` must mean `str.isspace()`.
/// Only use for patterns that do not put `\s` inside a character class.
pub fn py_regex(pattern: &str) -> Regex {
    let translated = pattern.replace(r"\s", r"[\s\x1C-\x1F]");
    // Patterns are compile-time constants covered by tests; failure here is a programming error.
    Regex::new(&translated).expect("static regex is valid")
}

/// `round(x, ndigits)` for floats: the decimal string correctly rounded with ties-to-even on the
/// exact binary value, converted back to the nearest double (CPython's algorithm).
pub fn round(x: f64, ndigits: usize) -> f64 {
    if !x.is_finite() {
        return x;
    }
    format!("{x:.ndigits$}").parse().unwrap_or(x)
}

/// `repr(float)`: shortest round-trip digits; scientific form when the decimal exponent is
/// < -4 or >= 16, written like CPython (`1e-05`, `1.5e+16`).
pub fn float_repr(x: f64) -> String {
    if x.is_nan() {
        return "nan".into();
    }
    if x.is_infinite() {
        return if x > 0.0 { "inf".into() } else { "-inf".into() };
    }
    let s = format!("{x:?}");
    match s.find('e') {
        None => s,
        Some(i) => {
            let (mant, exp) = (&s[..i], &s[i + 1..]);
            let (sign, digits) = match exp.strip_prefix('-') {
                Some(d) => ('-', d),
                None => ('+', exp),
            };
            let mant = mant.strip_suffix(".0").unwrap_or(mant);
            format!("{mant}e{sign}{digits:0>2}")
        }
    }
}

/// `format(x, 'g')` (precision 6).
pub fn format_g(x: f64) -> String {
    if !x.is_finite() {
        return float_repr(x);
    }
    if x == 0.0 {
        return if x.is_sign_negative() {
            "-0".into()
        } else {
            "0".into()
        };
    }
    const P: i32 = 6;
    let sci = format!("{:.*e}", (P - 1) as usize, x);
    let (mant, exp) = match sci.split_once('e') {
        Some(parts) => parts,
        None => return sci,
    };
    let exp: i32 = exp.parse().unwrap_or(0);
    if (-4..P).contains(&exp) {
        let decimals = (P - 1 - exp).max(0) as usize;
        strip_fraction_zeros(&format!("{x:.decimals$}"))
    } else {
        let mant = strip_fraction_zeros(mant);
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{mant}e{sign}{:0>2}", exp.abs())
    }
}

fn strip_fraction_zeros(s: &str) -> String {
    if s.contains('.') {
        s.trim_end_matches('0').trim_end_matches('.').to_owned()
    } else {
        s.to_owned()
    }
}

/// CPython's `Py_UNICODE_ISPRINTABLE` is false for general categories Cc, Cf, Cs, Co, Cn, Zl, Zp
/// and Zs (except the ASCII space). Unicode tables are the `regex` crate's.
fn is_printable(c: char) -> bool {
    static NON_PRINTABLE: std::sync::LazyLock<Regex> = std::sync::LazyLock::new(|| {
        Regex::new(r"^[\p{Cc}\p{Cf}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$")
            .expect("static regex is valid")
    });
    c == ' ' || !NON_PRINTABLE.is_match(c.encode_utf8(&mut [0; 4]))
}

/// `repr(str)`: single quotes unless the text contains `'` and no `"`; escapes backslash, the
/// quote, `\t \n \r`, and every other non-printable code point as CPython does (`\xNN`, `\uNNNN`,
/// `\UNNNNNNNN`). Printable non-ASCII text is kept.
pub fn str_repr(s: &str) -> String {
    let quote = if s.contains('\'') && !s.contains('"') {
        '"'
    } else {
        '\''
    };
    let mut out = String::with_capacity(s.len() + 2);
    out.push(quote);
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            c if c == quote => {
                out.push('\\');
                out.push(c);
            }
            c if c.is_ascii() && (c as u32) >= 0x20 && c != '\x7f' => out.push(c),
            c if c.is_ascii() || !is_printable(c) => match c as u32 {
                n @ 0..=0xff => out.push_str(&format!("\\x{n:02x}")),
                n @ 0x100..=0xffff => out.push_str(&format!("\\u{n:04x}")),
                n => out.push_str(&format!("\\U{n:08x}")),
            },
            c => out.push(c),
        }
    }
    out.push(quote);
    out
}

/// Python truthiness of a JSON value.
pub fn truthy(v: &Value) -> bool {
    match v {
        Value::Null => false,
        Value::Bool(b) => *b,
        Value::Number(n) => n.as_f64().is_some_and(|f| f != 0.0),
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(o) => !o.is_empty(),
    }
}

/// `str(value)` for a JSON-decoded value (`None`, `True`, ints, float repr, strings). Lists and
/// dicts print like Python's `str(list)` / `str(dict)`: elements and keys use `repr` (see
/// [`value_repr`]).
pub fn value_str(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        other => value_repr(other),
    }
}

/// `repr(value)` for a JSON-decoded value: `None`, `True`, ints, float repr, `str_repr` for
/// strings, `[a, b]` for lists and `{'k': v}` for dicts. Dict keys come out in the order the
/// `serde_json` map holds them; without serde_json's `preserve_order` feature that is sorted
/// order, where Python keeps insertion order (identical for dicts with at most one key).
/// Integers beyond `u64` were already turned into floats by the JSON parser.
pub fn value_repr(v: &Value) -> String {
    match v {
        Value::Null => "None".into(),
        Value::Bool(true) => "True".into(),
        Value::Bool(false) => "False".into(),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i.to_string()
            } else if let Some(u) = n.as_u64() {
                u.to_string()
            } else {
                float_repr(n.as_f64().unwrap_or(f64::NAN))
            }
        }
        Value::String(s) => str_repr(s),
        Value::Array(items) => {
            let parts: Vec<String> = items.iter().map(value_repr).collect();
            format!("[{}]", parts.join(", "))
        }
        Value::Object(map) => {
            let parts: Vec<String> = map
                .iter()
                .map(|(k, x)| format!("{}: {}", str_repr(k), value_repr(x)))
                .collect();
            format!("{{{}}}", parts.join(", "))
        }
    }
}

/// The integer a JSON value equals under Python `==`/hashing (`1`, `1.0` and `True` are the same
/// dict key). `None` for anything else.
pub fn int_key(v: &Value) -> Option<i64> {
    match v {
        Value::Bool(b) => Some(i64::from(*b)),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Some(i)
            } else {
                let f = n.as_f64()?;
                (f.fract() == 0.0 && f.abs() < 9.2e18).then_some(f as i64)
            }
        }
        _ => None,
    }
}

/// `Decimal(str(x))` for a JSON number (ints exactly, floats via their repr).
pub fn decimal_of(v: &Value) -> Option<Decimal> {
    match v {
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Some(Decimal::from(i))
            } else if let Some(u) = n.as_u64() {
                Some(Decimal::from(u))
            } else {
                decimal_of_f64(n.as_f64()?)
            }
        }
        Value::Bool(b) => Some(Decimal::from(i64::from(*b))),
        _ => None,
    }
}

/// `Decimal(str(f))` for a float.
pub fn decimal_of_f64(f: f64) -> Option<Decimal> {
    if !f.is_finite() {
        return None;
    }
    let repr = float_repr(f);
    Decimal::from_str(&repr)
        .ok()
        .or_else(|| Decimal::from_scientific(&repr).ok())
}

/// `str(Decimal)` for values with a non-positive exponent (rust_decimal cannot hold a positive
/// exponent such as `1E+2`; it is normalized to `100`).
pub fn decimal_str(d: &Decimal) -> String {
    let scale = d.scale() as i64;
    let mantissa = d.mantissa();
    let digits = mantissa.unsigned_abs().to_string();
    let adjusted = digits.len() as i64 - 1 - scale;
    if adjusted >= -6 {
        return d.to_string();
    }
    let sign = if mantissa < 0 { "-" } else { "" };
    let (head, tail) = digits.split_at(1);
    if tail.is_empty() {
        format!("{sign}{head}E{adjusted}")
    } else {
        format!("{sign}{head}.{tail}E{adjusted}")
    }
}

/// `datetime.fromisoformat(s)` returning the wall-clock (offset discarded, not converted) and
/// whether an offset was present. Accepts `YYYY-MM-DD` or `YYYYMMDD` (ASCII digits, year >= 1),
/// optionally followed by any single separator and `HH[:MM[:SS[.fraction]]]` (or `HHMM[SS]`) and
/// `Z` / `±HH[:MM[:SS]]`. Narrower than CPython 3.12, which also accepts ISO week dates, a
/// fraction after `HH` or `HH:MM`, an offset with a fraction, and one stray character before the
/// offset; those are rejected here.
pub fn fromisoformat(s: &str) -> Result<(NaiveDateTime, bool), String> {
    let err = || format!("Invalid isoformat string: {}", str_repr(s));
    // CPython reads the date fields as ASCII digits only (no sign, no padding spaces, which
    // chrono would accept) and rejects year 0.
    let digits = |r: std::ops::Range<usize>| {
        s.as_bytes()
            .get(r)
            .is_some_and(|b| b.iter().all(u8::is_ascii_digit))
    };
    let (fmt, len) = if s.as_bytes().get(4) == Some(&b'-') {
        if !(digits(0..4) && digits(5..7) && digits(8..10)) {
            return Err(err());
        }
        ("%Y-%m-%d", 10)
    } else if digits(0..8) {
        ("%Y%m%d", 8)
    } else {
        return Err(err());
    };
    // Bytes 0..len are ASCII here, so `len` is a char boundary.
    let date = NaiveDate::parse_from_str(&s[..len], fmt).map_err(|_| err())?;
    if date.year() == 0 {
        return Err(err());
    }
    let rest = &s[len..];
    if rest.is_empty() {
        return Ok((date.and_time(NaiveTime::MIN), false));
    }
    let mut chars = rest.chars();
    chars.next(); // any single separator character
    let rest = chars.as_str();
    let tz_at = rest.find(['Z', '+', '-']);
    let (time_s, tz_s) = match tz_at {
        Some(i) => (&rest[..i], Some(&rest[i..])),
        None => (rest, None),
    };
    let time = parse_time(time_s).ok_or_else(err)?;
    if let Some(tz) = tz_s {
        if !valid_offset(tz) {
            return Err(err());
        }
    }
    Ok((date.and_time(time), tz_s.is_some()))
}

fn parse_time(s: &str) -> Option<NaiveTime> {
    let (main, frac) = match s.find(['.', ',']) {
        Some(i) => (&s[..i], Some(&s[i + 1..])),
        None => (s, None),
    };
    let parts: Vec<&str> = if main.contains(':') {
        main.split(':').collect()
    } else {
        (0..main.len())
            .step_by(2)
            .map(|i| main.get(i..i + 2).unwrap_or(""))
            .collect()
    };
    if parts.is_empty()
        || parts.len() > 3
        || parts
            .iter()
            .any(|p| p.len() != 2 || !p.bytes().all(|b| b.is_ascii_digit()))
    {
        return None;
    }
    let n = |i: usize| {
        parts
            .get(i)
            .and_then(|p| p.parse::<u32>().ok())
            .unwrap_or(0)
    };
    let micros = match frac {
        None => 0,
        Some(f) if !f.is_empty() && f.bytes().all(|b| b.is_ascii_digit()) && parts.len() == 3 => {
            let six: String = f.chars().chain("000000".chars()).take(6).collect();
            six.parse::<u32>().ok()?
        }
        Some(_) => return None,
    };
    NaiveTime::from_hms_micro_opt(n(0), n(1), n(2), micros)
}

fn valid_offset(tz: &str) -> bool {
    if tz == "Z" {
        return true;
    }
    let body = &tz[1..];
    let digits: String = body.chars().filter(|c| *c != ':').collect();
    matches!(digits.len(), 2 | 4 | 6)
        && digits.bytes().all(|b| b.is_ascii_digit())
        && digits[..2].parse::<u32>().is_ok_and(|h| h < 24)
}

/// CPython 3.12 built-in `sum()` over floats with the default start `0`. The first item is
/// added to the int `0` (so `-0.0` becomes `0.0`); the rest use Neumaier's compensated summation,
/// and the compensation is added at the end when it is non-zero and finite. An empty sequence
/// gives `0.0` where Python returns the int `0`.
pub fn sum_floats<I: IntoIterator<Item = f64>>(items: I) -> f64 {
    let mut it = items.into_iter();
    let Some(first) = it.next() else {
        return 0.0;
    };
    let mut total = 0.0 + first;
    let mut c = 0.0;
    for x in it {
        let t = total + x;
        if total.abs() >= x.abs() {
            c += (total - t) + x;
        } else {
            c += (x - t) + total;
        }
        total = t;
    }
    if c != 0.0 && c.is_finite() {
        total += c;
    }
    total
}

/// Whether an `i64` converts to `f64` without rounding.
fn exact_f64(v: i64) -> bool {
    let m = v.unsigned_abs();
    m == 0 || 64 - m.leading_zeros() - m.trailing_zeros() <= 53
}

/// Python `a / b` for ints: the correctly rounded (ties-to-even) quotient. `None` when `b == 0`
/// (Python raises `ZeroDivisionError`).
pub fn int_true_div(a: i64, b: i64) -> Option<f64> {
    if b == 0 {
        return None;
    }
    if a == 0 {
        return Some(if b < 0 { -0.0 } else { 0.0 });
    }
    if exact_f64(a) && exact_f64(b) {
        // IEEE division of exact operands is correctly rounded.
        return Some(a as f64 / b as f64);
    }
    let negative = (a < 0) != (b < 0);
    let (num, den) = (a.unsigned_abs(), b.unsigned_abs());
    // num/den = (n128 / den) * 2^-shift with n128 holding num in the top bits of a u128, so the
    // integer quotient has at least 64 significant bits.
    let shift = 128 - (64 - num.leading_zeros()) as i32;
    let n128 = (num as u128) << shift;
    let den = u128::from(den);
    let (q, sticky) = (n128 / den, !n128.is_multiple_of(den));
    let bits = 128 - q.leading_zeros() as i32;
    let drop = bits - 53;
    let mut mant = q >> drop;
    let low = q & ((1u128 << drop) - 1);
    let half = 1u128 << (drop - 1);
    if low > half || (low == half && (sticky || mant & 1 == 1)) {
        mant += 1;
    }
    let mut exp = drop - shift;
    if mant == 1u128 << 53 {
        mant >>= 1;
        exp += 1;
    }
    // mant < 2^53 and |exp| < 130: the product below is exact.
    let scale = f64::from_bits(((1023 + exp) as u64) << 52);
    let value = mant as f64 * scale;
    Some(if negative { -value } else { value })
}

/// CPython's `_PyUnicode_TransformDecimalAndSpaceToASCII`, which `float(str)` and `int(str)` apply
/// first: every `str.isspace()` character becomes an ASCII space and every Unicode decimal digit
/// (general category Nd) becomes its ASCII digit. Other non-ASCII characters become `?`, which
/// no number accepts.
pub fn decimal_and_space_to_ascii(s: &str) -> String {
    if s.is_ascii() {
        return s.to_owned();
    }
    s.chars()
        .map(|c| {
            if c.is_ascii() {
                c
            } else if is_space(c) {
                ' '
            } else {
                match unicode_decimal(c) {
                    Some(d) => char::from(b'0' + d),
                    None => '?',
                }
            }
        })
        .collect()
}

/// `str.isdecimal()` for one character (what `\d` matches in a str pattern): Unicode general
/// category Nd.
pub fn is_decimal(c: char) -> bool {
    c.is_ascii_digit() || (!c.is_ascii() && unicode_decimal(c).is_some())
}

/// The value of a Unicode decimal digit (general category Nd). Unicode encodes those digits in
/// runs of exactly ten consecutive code points, 0 to 9, so the value is the offset from the
/// start of the maximal Nd range containing `c`, modulo 10.
fn unicode_decimal(c: char) -> Option<u8> {
    static ND: std::sync::LazyLock<Regex> =
        std::sync::LazyLock::new(|| Regex::new(r"^\p{Nd}$").expect("static regex is valid"));
    let is_nd =
        |cp: u32| char::from_u32(cp).is_some_and(|ch| ND.is_match(ch.encode_utf8(&mut [0; 4])));
    let cp = c as u32;
    if !is_nd(cp) {
        return None;
    }
    let mut start = cp;
    while start > 0 && is_nd(start - 1) {
        start -= 1;
    }
    u8::try_from((cp - start) % 10).ok()
}

/// C `isspace` in the "C" locale (CPython's `Py_ISSPACE`): space, `\t \n \v \f \r`. After
/// [`decimal_and_space_to_ascii`], `float()` and `int()` strip only these.
fn is_c_space(c: char) -> bool {
    matches!(c, ' ' | '\t' | '\n' | '\x0b' | '\x0c' | '\r')
}

/// Python `float(s)` for a string: Unicode decimal digits and whitespace are first mapped to
/// ASCII ([`decimal_and_space_to_ascii`]), surrounding C whitespace is ignored and single
/// underscores between digits are allowed; `inf`, `infinity` and `nan` in any case.
pub fn float_of_str(s: &str) -> Option<f64> {
    let ascii = decimal_and_space_to_ascii(s);
    let t = ascii.trim_matches(is_c_space);
    let cleaned: String = if t.contains('_') {
        let chars: Vec<char> = t.chars().collect();
        for (i, c) in chars.iter().enumerate() {
            if *c == '_' {
                let before = i.checked_sub(1).and_then(|j| chars.get(j));
                let after = chars.get(i + 1);
                if !(before.is_some_and(char::is_ascii_digit)
                    && after.is_some_and(char::is_ascii_digit))
                {
                    return None;
                }
            }
        }
        chars.into_iter().filter(|c| *c != '_').collect()
    } else {
        t.to_owned()
    };
    if !cleaned.is_ascii() {
        return None;
    }
    cleaned.parse::<f64>().ok()
}

/// Python's error text for `float(x)` / `int(x)` of an unsupported JSON type.
fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Null => "NoneType",
        Value::Bool(_) => "bool",
        Value::Number(_) => "float",
        Value::String(_) => "str",
        Value::Array(_) => "list",
        Value::Object(_) => "dict",
    }
}

/// Python `float(x)` for a JSON-decoded value: numbers and booleans convert, strings parse as
/// [`float_of_str`], anything else is the `TypeError`/`ValueError` message.
pub fn float_of_value(v: &Value) -> Result<f64, String> {
    match v {
        Value::Bool(b) => Ok(if *b { 1.0 } else { 0.0 }),
        Value::Number(n) => n
            .as_f64()
            .ok_or_else(|| "float() argument out of range".to_owned()),
        Value::String(s) => float_of_str(s)
            .ok_or_else(|| format!("could not convert string to float: {}", str_repr(s))),
        other => Err(format!(
            "float() argument must be a string or a real number, not '{}'",
            type_name(other)
        )),
    }
}

/// Python `int(f)` for a float, as an `i64`: truncation toward zero. `Err` for NaN and the
/// infinities (Python raises) and for results outside `i64` (Python returns a big int).
pub fn int_of_float(f: f64) -> Result<i64, String> {
    if f.is_nan() {
        return Err("cannot convert float NaN to integer".into());
    }
    if f.is_infinite() {
        return Err("cannot convert float infinity to integer".into());
    }
    let t = f.trunc();
    // -2^63 is exact; 2^63 is the first value that does not fit.
    if (-9_223_372_036_854_775_808.0..9_223_372_036_854_775_808.0).contains(&t) {
        Ok(t as i64)
    } else {
        Err(format!("int({}) does not fit in i64", float_repr(f)))
    }
}

/// `str(int(f))` for a float, exact for every finite value (Python's ints are unbounded).
pub fn int_str_of_float(f: f64) -> Result<String, String> {
    if f.is_nan() {
        return Err("cannot convert float NaN to integer".into());
    }
    if f.is_infinite() {
        return Err("cannot convert float infinity to integer".into());
    }
    let t = f.trunc();
    if t == 0.0 {
        return Ok("0".into());
    }
    // Fixed-precision formatting of an integral double prints its exact decimal value.
    Ok(format!("{t:.0}"))
}

/// Python `int(s)` for a string: Unicode decimal digits and whitespace are first mapped to ASCII
/// ([`decimal_and_space_to_ascii`]); then an optional sign and digits with single underscores
/// between digits, surrounding C whitespace ignored. Values outside `i64` are an error (Python
/// returns a big int).
pub fn int_of_str(s: &str) -> Result<i64, String> {
    let err = || format!("invalid literal for int() with base 10: {}", str_repr(s));
    let ascii = decimal_and_space_to_ascii(s);
    let t = ascii.trim_matches(is_c_space);
    let (sign, digits) = match t.as_bytes().first() {
        Some(b'-') => (-1i128, &t[1..]),
        Some(b'+') => (1, &t[1..]),
        _ => (1, t),
    };
    let bytes = digits.as_bytes();
    if bytes.is_empty() || !bytes[0].is_ascii_digit() || !bytes[bytes.len() - 1].is_ascii_digit() {
        return Err(err());
    }
    let mut value: i128 = 0;
    let mut prev_underscore = false;
    for &b in bytes {
        if b == b'_' {
            if prev_underscore {
                return Err(err());
            }
            prev_underscore = true;
            continue;
        }
        if !b.is_ascii_digit() {
            return Err(err());
        }
        prev_underscore = false;
        value = value
            .checked_mul(10)
            .and_then(|v| v.checked_add(i128::from(b - b'0')))
            .ok_or_else(|| format!("int({}) does not fit in i64", str_repr(s)))?;
    }
    i64::try_from(sign * value).map_err(|_| format!("int({}) does not fit in i64", str_repr(s)))
}

/// `format(n, ',')` for an integer: comma thousands separators.
pub fn group_thousands(n: i128) -> String {
    let digits = n.unsigned_abs().to_string();
    let mut out = String::with_capacity(digits.len() + digits.len() / 3 + 1);
    if n < 0 {
        out.push('-');
    }
    for (i, c) in digits.chars().enumerate() {
        if i > 0 && (digits.len() - i).is_multiple_of(3) {
            out.push(',');
        }
        out.push(c);
    }
    out
}

/// A compiled regex with Python `re` semantics (str pattern, optionally `re.I`) for the
/// constructs the ported communication patterns use: literals, alternation, groups, greedy
/// quantifiers, character classes, `\d`, `\s` and `\b`. Python and the Rust `regex` crate
/// differ there (part 1 review, R9), and this type closes the gaps:
///
/// - `\s` means `str.isspace()` (the pattern is compiled with [`py_regex`]'s translation);
/// - `\b` uses Python's word characters (`\w` = Unicode letters `L*`, numbers `N*` and `_`; Rust
///   counts combining marks, connector punctuation, join controls and `Other_Alphabetic`
///   symbols as word characters and not `No` numbers such as `½`). The text is matched in a
///   normalized copy where each character whose word status differs is replaced, one character
///   for one, by a stand-in with Python's status (`ж` for a word character, `☃` otherwise);
///   neither stand-in can match a pattern literal, a digit or a space;
/// - with `re.I`, Python also matches `İ` (U+0130) and `ı` (U+0131) for `i`, which Rust's
///   simple case folding does not: they are replaced by `i` in the normalized copy (Python's
///   other non-ASCII equivalents of ASCII letters, `K` for `k` and `ſ` for `s`, Rust folds too).
///
/// Match positions and groups are reported in the original text. `\d` is Unicode `Nd` in both
/// engines; the Rust engine's leftmost-first semantics equal Python's backtracking for these
/// patterns (no backreferences or lookaround). Unicode tables: CPython 3.12 uses Unicode 15.0,
/// the `regex` crate a newer version; characters assigned after 15.0 may differ (tested).
#[derive(Debug, Clone)]
pub struct PyRegex {
    re: Regex,
    ignore_case: bool,
}

/// A match of [`PyRegex::search`]: byte ranges in the original text.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PyMatch<'t> {
    text: &'t str,
    groups: Vec<Option<(usize, usize)>>,
}

impl<'t> PyMatch<'t> {
    /// `m.group(i)` (0 is the whole match); `None` when the group did not participate.
    pub fn group(&self, i: usize) -> Option<&'t str> {
        self.groups
            .get(i)
            .copied()
            .flatten()
            .map(|(a, b)| &self.text[a..b])
    }

    /// `m.start()`, `m.end()` in bytes of the original text.
    pub fn span(&self) -> (usize, usize) {
        self.groups.first().copied().flatten().unwrap_or((0, 0))
    }
}

fn rust_word(c: char) -> bool {
    static W: std::sync::OnceLock<Regex> = std::sync::OnceLock::new();
    let re = W.get_or_init(|| Regex::new(r"\A\w\z").expect("static regex is valid"));
    let mut buf = [0u8; 4];
    re.is_match(c.encode_utf8(&mut buf))
}

/// CPython's `\w` for str patterns: `str.isalnum()` or `_` (general categories `L*` and `N*`).
pub fn is_py_word(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphanumeric() || c == '_';
    }
    static W: std::sync::OnceLock<Regex> = std::sync::OnceLock::new();
    let re = W.get_or_init(|| Regex::new(r"\A[\p{L}\p{N}]\z").expect("static regex is valid"));
    let mut buf = [0u8; 4];
    re.is_match(c.encode_utf8(&mut buf))
}

impl PyRegex {
    /// Compile a Python pattern (`re.compile(pattern)`, or with `re.I` when `ignore_case`).
    /// Patterns are compile-time constants covered by tests; failure is a programming error.
    pub fn new(pattern: &str, ignore_case: bool) -> Self {
        let translated = pattern.replace(r"\s", r"[\s\x1C-\x1F]");
        let full = if ignore_case {
            format!("(?i){translated}")
        } else {
            translated
        };
        Self {
            re: Regex::new(&full).expect("static regex is valid"),
            ignore_case,
        }
    }

    /// The normalized copy of `text` and, for each of its byte offsets at a character boundary
    /// (and its end), the matching offset in `text`.
    fn normalize(&self, text: &str) -> (String, Vec<usize>) {
        let mut out = String::with_capacity(text.len());
        let mut at = Vec::with_capacity(text.len() + 1);
        for (i, c) in text.char_indices() {
            let mapped = if c.is_ascii() {
                c
            } else if self.ignore_case && (c == '\u{130}' || c == '\u{131}') {
                'i'
            } else {
                let py = is_py_word(c);
                if py == rust_word(c) {
                    c
                } else if py {
                    'ж'
                } else {
                    '☃'
                }
            };
            let start = out.len();
            out.push(mapped);
            at.resize(start + 1, i);
            at[start] = i;
        }
        let end = out.len();
        at.resize(end + 1, text.len());
        at[end] = text.len();
        (out, at)
    }

    /// `pattern.search(text)`: the first match, with every group.
    pub fn search<'t>(&self, text: &'t str) -> Option<PyMatch<'t>> {
        let (norm, at) = self.normalize(text);
        let caps = self.re.captures(&norm)?;
        let groups = (0..caps.len())
            .map(|i| caps.get(i).map(|m| (at[m.start()], at[m.end()])))
            .collect();
        Some(PyMatch { text, groups })
    }

    /// `bool(pattern.search(text))`.
    pub fn is_match(&self, text: &str) -> bool {
        let (norm, _) = self.normalize(text);
        self.re.is_match(&norm)
    }

    /// `list(pattern.finditer(text))`: every non-overlapping match, left to right, with every
    /// group. Only for patterns that cannot match the empty string (Python and the regex crate
    /// place empty matches differently); for the others both engines resume at the end of the
    /// previous match with leftmost-first semantics.
    pub fn search_all<'t>(&self, text: &'t str) -> Vec<PyMatch<'t>> {
        let (norm, at) = self.normalize(text);
        self.re
            .captures_iter(&norm)
            .map(|caps| PyMatch {
                text,
                groups: (0..caps.len())
                    .map(|i| caps.get(i).map(|m| (at[m.start()], at[m.end()])))
                    .collect(),
            })
            .collect()
    }
}

/// CPython 3.12's default `sys.get_int_max_str_digits()`: `int()` of a decimal string with more
/// digits than this (leading zeros included, underscores not) raises `ValueError`.
const PY_INT_MAX_STR_DIGITS: usize = 4300;

/// `str(int(s))` for any size up to CPython's digit limit: the canonical decimal form of
/// Python's `int(s)` (same syntax as [`int_of_str`]: Unicode digits and spaces mapped to ASCII,
/// surrounding whitespace, an optional sign, single underscores between digits). More than
/// 4,300 digits is an error, as in CPython 3.12 (`sys.get_int_max_str_digits()`).
pub fn int_literal(s: &str) -> Result<String, String> {
    let err = || format!("invalid literal for int() with base 10: {}", str_repr(s));
    let ascii = decimal_and_space_to_ascii(s);
    let t = ascii.trim_matches(is_c_space);
    let (negative, digits) = match t.as_bytes().first() {
        Some(b'-') => (true, &t[1..]),
        Some(b'+') => (false, &t[1..]),
        _ => (false, t),
    };
    let bytes = digits.as_bytes();
    if bytes.is_empty() || !bytes[0].is_ascii_digit() || !bytes[bytes.len() - 1].is_ascii_digit() {
        return Err(err());
    }
    let mut out = String::with_capacity(bytes.len() + 1);
    let mut prev_underscore = false;
    let mut digit_count = 0usize;
    for &b in bytes {
        if b == b'_' {
            if prev_underscore {
                return Err(err());
            }
            prev_underscore = true;
            continue;
        }
        if !b.is_ascii_digit() {
            return Err(err());
        }
        prev_underscore = false;
        digit_count += 1;
        if !(out.is_empty() && b == b'0') {
            out.push(char::from(b));
        }
    }
    if digit_count > PY_INT_MAX_STR_DIGITS {
        return Err(format!(
            "Exceeds the limit ({PY_INT_MAX_STR_DIGITS} digits) for integer string conversion: value has {digit_count} digits; use sys.set_int_max_str_digits() to increase the limit"
        ));
    }
    if out.is_empty() {
        return Ok("0".into());
    }
    if negative {
        out.insert(0, '-');
    }
    Ok(out)
}

/// `base64.b64decode(s)` with Python's defaults (`validate=False`): a `str` argument must be
/// ASCII; characters outside the standard alphabet are skipped; decoding stops at a complete
/// padding sequence; a dangling single character or missing padding is an error
/// (`binascii.Error`). A port of CPython 3.12 `binascii.a2b_base64` in non-strict mode. `Err`
/// carries Python's message; every error is a `ValueError` in Python.
pub fn b64decode(s: &str) -> Result<Vec<u8>, String> {
    if !s.is_ascii() {
        return Err("string argument should contain only ASCII characters".into());
    }
    fn sextet(c: u8) -> Option<u8> {
        match c {
            b'A'..=b'Z' => Some(c - b'A'),
            b'a'..=b'z' => Some(c - b'a' + 26),
            b'0'..=b'9' => Some(c - b'0' + 52),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    }
    let mut out = Vec::with_capacity(s.len() / 4 * 3 + 3);
    let mut quad_pos = 0u8;
    let mut leftchar = 0u8;
    let mut pads = 0u8;
    for &c in s.as_bytes() {
        if c == b'=' {
            if quad_pos >= 2 {
                pads += 1;
                if quad_pos + pads >= 4 {
                    return Ok(out);
                }
            }
            continue;
        }
        let Some(v) = sextet(c) else {
            continue;
        };
        pads = 0;
        match quad_pos {
            0 => {
                quad_pos = 1;
                leftchar = v;
            }
            1 => {
                quad_pos = 2;
                out.push((leftchar << 2) | (v >> 4));
                leftchar = v & 0x0f;
            }
            2 => {
                quad_pos = 3;
                out.push((leftchar << 4) | (v >> 2));
                leftchar = v & 0x03;
            }
            _ => {
                quad_pos = 0;
                out.push((leftchar << 6) | v);
                leftchar = 0;
            }
        }
    }
    match quad_pos {
        0 => Ok(out),
        1 => Err(format!(
            "Invalid base64-encoded string: number of data characters ({}) cannot be 1 more than a multiple of 4",
            out.len() / 3 * 4 + 1
        )),
        _ => Err("Incorrect padding".into()),
    }
}

/// Append `json.dumps`'s encoding of a string (`ensure_ascii=True`: non-ASCII and control
/// characters as lower-case `\uXXXX`, astral characters as surrogate pairs).
pub fn json_push_str(out: &mut String, s: &str) {
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            ' '..='~' => out.push(ch),
            _ => {
                let mut buf = [0u16; 2];
                for unit in ch.encode_utf16(&mut buf) {
                    out.push_str(&format!("\\u{unit:04x}"));
                }
            }
        }
    }
    out.push('"');
}

/// Append `json.dumps(v, separators=(",", ":"))` (ensure_ascii, Python float repr, map keys in
/// the map's own order).
pub fn json_push_compact(out: &mut String, v: &Value) {
    match v {
        Value::Null => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                out.push_str(&i.to_string());
            } else if let Some(u) = n.as_u64() {
                out.push_str(&u.to_string());
            } else {
                out.push_str(&float_repr(n.as_f64().unwrap_or(f64::NAN)));
            }
        }
        Value::String(s) => json_push_str(out, s),
        Value::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                json_push_compact(out, item);
            }
            out.push(']');
        }
        Value::Object(map) => {
            out.push('{');
            for (i, (k, item)) in map.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                json_push_str(out, k);
                out.push(':');
                json_push_compact(out, item);
            }
            out.push('}');
        }
    }
}

/// `json.dumps(v, separators=(",", ":"))`.
pub fn json_dumps_compact(v: &Value) -> String {
    let mut out = String::new();
    json_push_compact(&mut out, v);
    out
}

/// `json.loads(b)` for bytes: an optional UTF-8 byte-order mark, then UTF-8 JSON. Narrower than
/// Python: UTF-16/32 input, `NaN`/`Infinity` literals, lone surrogate escapes and nesting deeper
/// than `serde_json`'s 128 levels are errors here.
pub fn json_loads_bytes(b: &[u8]) -> Result<Value, String> {
    let b = b.strip_prefix(b"\xef\xbb\xbf").unwrap_or(b);
    serde_json::from_slice(b).map_err(|e| e.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn numeric_helpers_match_cpython_examples() {
        // Expected values are CPython 3.12 results.
        assert_eq!(sum_floats([0.1; 10]), 1.0);
        assert_eq!(sum_floats([0.1, 0.2, 0.3]), 0.6);
        assert_eq!(sum_floats([1e100, 1.0, -1e100]), 1.0);
        assert_eq!(sum_floats([-0.0]).to_bits(), 0.0f64.to_bits());
        assert_eq!(int_true_div(1, 3), Some(1.0 / 3.0));
        assert_eq!(int_true_div(5, 0), None);
        // 2^53 + 1 is not exact as a double; Python divides the exact integers.
        assert_eq!(
            int_true_div(9_007_199_254_740_993, 3),
            Some(3002399751580331.0)
        );
        assert_eq!(int_true_div(i64::MAX, 7), Some(1.3176245766935393e18));
        assert_eq!(
            int_true_div(-9_007_199_254_740_993, 2),
            Some(-4503599627370496.0)
        );
        assert_eq!(float_of_str(" 1_000.5 "), Some(1000.5));
        assert_eq!(float_of_str("1__0"), None);
        assert_eq!(float_of_str("_1"), None);
        assert!(float_of_str("-Infinity").is_some_and(|f| f == f64::NEG_INFINITY));
        assert_eq!(int_of_float(-2.9), Ok(-2));
        assert!(int_of_float(f64::NAN).is_err());
        assert_eq!(
            int_str_of_float(1e30).as_deref(),
            Ok("1000000000000000019884624838656")
        );
        assert_eq!(int_str_of_float(-0.5).as_deref(), Ok("0"));
        assert_eq!(int_str_of_float(800.0).as_deref(), Ok("800"));
        assert_eq!(int_of_str(" -1_2 "), Ok(-12));
        assert!(int_of_str("5.0").is_err());
        assert!(int_of_str("1__2").is_err());
        assert_eq!(group_thousands(1_234_567), "1,234,567");
        assert_eq!(group_thousands(-1_000), "-1,000");
        assert_eq!(group_thousands(999), "999");
    }

    #[test]
    fn repr_and_g_match_cpython_examples() {
        assert_eq!(float_repr(4.0), "4.0");
        assert_eq!(float_repr(1e-5), "1e-05");
        assert_eq!(float_repr(1.5e16), "1.5e+16");
        assert_eq!(float_repr(1e16), "1e+16");
        assert_eq!(float_repr(0.0001), "0.0001");
        assert_eq!(format_g(4.0), "4");
        assert_eq!(format_g(36.123456), "36.1235");
        assert_eq!(format_g(1234567.0), "1.23457e+06");
        assert_eq!(format_g(0.0001234), "0.0001234");
        assert_eq!(format_g(0.00001234), "1.234e-05");
        assert_eq!(format_g(999999.5), "1e+06");
        assert_eq!(round(0.125, 2), 0.12);
        assert_eq!(round(0.375, 2), 0.38);
        assert_eq!(round(2.675, 1), 2.7);
        assert_eq!(str_repr("a'b"), "\"a'b\"");
        assert_eq!(str_repr("ROOF"), "'ROOF'");
        assert_eq!(title("LOS ANGELES"), "Los Angeles");
    }

    #[test]
    fn fromisoformat_forms() {
        let (dt, tz) = fromisoformat("2026-12-01T00:00:00-05:00").unwrap();
        assert_eq!(dt.to_string(), "2026-12-01 00:00:00");
        assert!(tz);
        let (dt, tz) = fromisoformat("2023-11-02T00:00:00.000").unwrap();
        assert_eq!(dt.to_string(), "2023-11-02 00:00:00");
        assert!(!tz);
        assert!(fromisoformat("2023-11-02").is_ok());
        assert!(fromisoformat("not a date").is_err());
        assert!(fromisoformat("2023-13-02").is_err());
        // CPython 3.12 rejects these (year 0, padded or signed fields, lower-case `z`); chrono
        // alone would accept them.
        for bad in [
            "0000-01-01",
            "2023- 1-02",
            "-023-11-02",
            "2023-11-02T00:00:00z",
            "+0231102",
            "2023110 ",
        ] {
            assert!(fromisoformat(bad).is_err(), "{bad}");
        }
        assert_eq!(
            fromisoformat("0001-01-01").unwrap().0.to_string(),
            "0001-01-01 00:00:00"
        );
        assert_eq!(
            fromisoformat("20231102").unwrap().0.to_string(),
            "2023-11-02 00:00:00"
        );
        assert!(fromisoformat("2023-11-02T00:00:00Z").unwrap().1);
    }

    #[test]
    fn str_repr_escapes_non_printable_like_cpython() {
        // Expected values are CPython 3.12 `repr()` output.
        assert_eq!(str_repr("\u{a0}"), r"'\xa0'");
        assert_eq!(str_repr("\u{85}"), r"'\x85'");
        assert_eq!(str_repr("\u{200b}X"), r"'\u200bX'");
        assert_eq!(str_repr("\u{e0001}"), r"'\U000e0001'");
        assert_eq!(
            str_repr("\u{1f600}\u{e9}\u{65e5}"),
            "'\u{1f600}\u{e9}\u{65e5}'"
        );
    }
}
